// Self-check: click "Run the self-check". It clicks your buttons for you,
// then puts the page back as it was. Do not edit this file.
document.querySelector('#run-check').addEventListener('click', () => {
  const out = document.querySelector('#self-check');
  out.replaceChildren();
  const results = [];
  function check(name, fn, hint) {
    let ok = false;
    try { ok = fn() === true; } catch (e) { ok = false; hint += ' (error: ' + e.message + ')'; }
    results.push({ name, ok, hint });
  }
  const cards = () => document.querySelectorAll('#product-list .product-card');
  const listItems = () => document.querySelectorAll('#shopping-list li');
  const select = document.querySelector('#category');
  const choose = value => { select.value = value; select.dispatchEvent(new Event('change')); };
  const sample = NKWEN.products[0];

  check('1. createProductCard returns a card that is not on the page yet', () => {
    const card = createProductCard(sample);
    return card instanceof HTMLLIElement && card.classList.contains('product-card') && !card.isConnected;
  }, 'Return the <li> you built. Do not append it inside createProductCard.');
  check('2. A card shows the name, category and price as text', () => {
    const card = createProductCard(sample);
    return card.querySelector('h3').textContent === sample.name &&
      card.textContent.includes(sample.category) &&
      card.querySelector('.price').textContent.includes('FCFA');
  }, 'Use an <h3> for the name and the classes "category" and "price".');
  check('3. Every product has a card when the page loads', () => cards().length === NKWEN.products.length, 'Call renderProducts(NKWEN.products) at the end of cards.js.');
  check('4. Choosing a category shows only its products', () => {
    const category = NKWEN.categories[NKWEN.categories.length - 1];
    choose(category);
    const expected = NKWEN.products.filter(p => p.category === category).length;
    const ok = cards().length === expected;
    choose('All');
    return ok && cards().length === NKWEN.products.length;
  }, 'Listen for "change" on the select, filter, then call renderProducts. Empty the list first.');
  check('5. "Add to list" adds one item, and only once', () => {
    const button = cards()[0].querySelector('button');
    const before = listItems().length;
    button.click();
    button.click();
    return listItems().length === before + 1 || (before > 0 && listItems().length === before);
  }, 'Check for an existing [data-id] before you add.');
  check('6. The empty message hides when the list has items', () => document.querySelector('#list-empty').hidden === true, 'Call updateEmptyMessage() after adding.');
  check('7. "Remove" removes only its own item and the message comes back', () => {
    const item = document.querySelector(`#shopping-list li[data-id="${NKWEN.products[0].id}"]`);
    const before = listItems().length;
    item.querySelector('button').click();
    return listItems().length === before - 1 && (listItems().length > 0 || document.querySelector('#list-empty').hidden === false);
  }, 'In the Remove listener, call item.remove() on the <li> you created, then updateEmptyMessage().');

  results.forEach(r => {
    const li = document.createElement('li');
    li.className = r.ok ? 'pass' : 'fail';
    li.textContent = (r.ok ? 'PASS ' : 'NOT YET ') + r.name + (r.ok ? '' : ' (hint: ' + r.hint + ')');
    out.append(li);
  });
  console.log(`Self-check: ${results.filter(r => r.ok).length} of ${results.length} passed`);
});
